def split_words(text: str) -> list[str]:
    words: list[str] = []
    parts: list[str] = []
    in_word = False
    length = len(text)
    index = 0
    separators = (" ", "\t", "\n")
    dq_escapable = ('"', "\\", "$", "`")

    while index < length:
        char = text[index]
        if char in separators:
            if in_word:
                words.append("".join(parts))
                parts = []
                in_word = False
            index += 1
        elif char == "#" and not in_word:
            newline_pos = text.find("\n", index)
            if newline_pos == -1:
                index = length
            else:
                index = newline_pos
        elif char == "\\":
            if index + 1 >= length:
                raise ValueError("trailing backslash")
            next_char = text[index + 1]
            if next_char == "\n":
                index += 2
            else:
                parts.append(next_char)
                in_word = True
                index += 2
        elif char == "'":
            close_pos = text.find("'", index + 1)
            if close_pos == -1:
                raise ValueError("unclosed single quote")
            parts.append(text[index + 1:close_pos])
            in_word = True
            index = close_pos + 1
        elif char == '"':
            in_word = True
            index += 1
            closed = False
            while index < length:
                inner = text[index]
                if inner == '"':
                    index += 1
                    closed = True
                    break
                if inner == "\\":
                    if index + 1 >= length:
                        raise ValueError("unclosed double quote")
                    next_char = text[index + 1]
                    if next_char in dq_escapable:
                        parts.append(next_char)
                        index += 2
                    elif next_char == "\n":
                        index += 2
                    else:
                        parts.append("\\")
                        index += 1
                else:
                    parts.append(inner)
                    index += 1
            if not closed:
                raise ValueError("unclosed double quote")
        else:
            parts.append(char)
            in_word = True
            index += 1

    if in_word:
        words.append("".join(parts))
    return words
